// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;
    function setUp() public { c = new BaseEscalationManager(address(this)); }

    function testFuzz_property(bytes32 assertionId) public {

        bytes memory sig = abi.encodeWithSignature("getAssertionPolicy(bytes32)", assertionId);
        (bool ok, bytes memory ret) = address(c).staticcall(sig);
        require(ok, "call failed");

        (bool blockAssertion, bool arbitrateViaEscalationManager, bool discardOracle, bool validateDisputers) = abi.decode(ret, (bool, bool, bool, bool));

        assertTrue(!arbitrateViaEscalationManager);
    }
}
